-- Create "pm_settings" table
CREATE TABLE "pm_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "new_message_subject" text NOT NULL, "new_message_body" text NOT NULL, PRIMARY KEY ("id"));
-- Create "pm_threads" table
CREATE TABLE "pm_threads" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "subject" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), PRIMARY KEY ("id"));
-- Create index "pmthread_updated_at" to table: "pm_threads"
CREATE INDEX "pmthread_updated_at" ON "pm_threads" ("updated_at");
-- Create index "pmthread_created_at" to table: "pm_threads"
CREATE INDEX "pmthread_created_at" ON "pm_threads" ("created_at");
-- Create "pm_messages" table
CREATE TABLE "pm_messages" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "body" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "author_id" bigint NULL, "thread_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "pm_messages_users_author" FOREIGN KEY ("author_id") REFERENCES "users" ("id") ON DELETE SET NULL, CONSTRAINT "pm_messages_pm_threads_messages" FOREIGN KEY ("thread_id") REFERENCES "pm_threads" ("id") ON DELETE CASCADE);
-- Create index "pmmessage_thread_id_created_at" to table: "pm_messages"
CREATE INDEX "pmmessage_thread_id_created_at" ON "pm_messages" ("thread_id", "created_at");
-- Create index "pmmessage_thread_id_id" to table: "pm_messages"
CREATE INDEX "pmmessage_thread_id_id" ON "pm_messages" ("thread_id", "id");
-- Create index "pmmessage_author_id_created_at" to table: "pm_messages"
CREATE INDEX "pmmessage_author_id_created_at" ON "pm_messages" ("author_id", "created_at");
-- Create "pm_thread_members" table
CREATE TABLE "pm_thread_members" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "is_new" boolean NOT NULL DEFAULT true, "deleted" boolean NOT NULL DEFAULT false, "joined_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "thread_id" bigint NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "pm_thread_members_pm_threads_members" FOREIGN KEY ("thread_id") REFERENCES "pm_threads" ("id") ON DELETE CASCADE, CONSTRAINT "pm_thread_members_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE);
-- Create index "pmthreadmember_user_id_deleted_is_new" to table: "pm_thread_members"
CREATE INDEX "pmthreadmember_user_id_deleted_is_new" ON "pm_thread_members" ("user_id", "deleted", "is_new");
-- Create index "pmthreadmember_user_id_deleted_is_new_thread_id" to table: "pm_thread_members"
CREATE INDEX "pmthreadmember_user_id_deleted_is_new_thread_id" ON "pm_thread_members" ("user_id", "deleted", "is_new", "thread_id");
-- Create index "pmthreadmember_thread_id_deleted" to table: "pm_thread_members"
CREATE INDEX "pmthreadmember_thread_id_deleted" ON "pm_thread_members" ("thread_id", "deleted");
-- Create index "pm_thread_members_thread_user" to table: "pm_thread_members"
CREATE UNIQUE INDEX "pm_thread_members_thread_user" ON "pm_thread_members" ("thread_id", "user_id");
-- Create "pm_user_settings" table
CREATE TABLE "pm_user_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "mail_new_message" boolean NOT NULL DEFAULT true, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "pm_user_settings_users_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE);
-- Create index "pmusersettings_user_id" to table: "pm_user_settings"
CREATE UNIQUE INDEX "pmusersettings_user_id" ON "pm_user_settings" ("user_id");
